<?php namespace Workspace; ?>
<div class="oss-guest"><header class="panel inset"><p>Open-source · CajeerWorkspace</p><h1><?= h($project['public_title']) ?></h1><p class="criteria-text"><?= h($project['description']) ?></p><p><a href="<?= h('https://github.com/'.$project['upstream']) ?>" rel="noopener noreferrer">GitHub · <?= h($project['upstream']) ?></a> · <a href="<?= h(url('oss.join')) ?>">Вход contributor</a> · <a href="<?= h(url('oss.export',['slug'=>$project['slug'],'n'=>$page])) ?>">JSON этой страницы</a></p></header>
<section class="panel inset"><h2>Публичные вехи</h2><?php if (!$milestones): ?><p>Вехи не опубликованы.</p><?php endif ?><?php foreach ($milestones as $m): ?><article class="panel inset"><h3><?= h($m['public_title']) ?></h3><p><?= h(MILESTONE_STATES[$m['state']]) ?> · <?= h(displayDate($m['due_on'])) ?></p><p class="criteria-text"><?= h($m['description']) ?></p></article><?php endforeach ?></section>
<section class="panel inset"><h2>Release notes</h2><?php if (!$releases): ?><p>Выпусков пока нет.</p><?php endif ?><?php foreach ($releases as $r): ?><article class="panel inset"><h3><?= h($r['tag']) ?> — <?= h($r['title']) ?></h3><p><?= h(gmdate('Y-m-d H:i',(int)$r['published_at'])) ?> UTC</p><p class="criteria-text"><?= h($r['notes']) ?></p><?php if ($r['items']): ?><h4>Принятые вклады</h4><ul><?php foreach ($r['items'] as $i): ?><li><span class="criteria-text"><?= h($i['public_note']) ?></span> · <a href="<?= h($i['upstream_url']) ?>" rel="noopener noreferrer">Upstream</a></li><?php endforeach ?></ul><?php endif ?></article><?php endforeach ?></section>
<nav aria-label="Страницы истории"><?php if ($page>1): ?><a href="<?= h(url('oss.public',['slug'=>$project['slug'],'n'=>$page-1])) ?>">← Предыдущая</a><?php endif ?> <?php if ($next_page): ?><a href="<?= h(url('oss.public',['slug'=>$project['slug'],'n'=>$next_page])) ?>">Следующая →</a><?php endif ?></nav></div>
